INSERT INTO public.trofeus (slug, evento, ano, data, cidade, edicao, categoria, tipo, foto_alt, historia, foto_url, colocacao, nivel, publicado)
VALUES
  ('2026-caveiras-100-limites', 'Caveiras 100 Limites — 10 anos', 2026, NULL, 'Sairé — PE', '10 anos', 'Placa de participação', 'placa', 'Placa retangular Caveiras 100 Limites, 2026, 10 anos, Bate e Fica.', 'Placa comemorativa dos 10 anos do Caveiras 100 Limites. A peça traz “Bate e Fica” e a inscrição “28 a 01 de março”. O intervalo completo de datas não foi confirmado.', '/media/trofeus/2026-caveiras-100-limites.jpg', 'Participação', 'laco', true),
  ('2026-car-rock-festival-lajedo', 'Car Rock Festival — Lajedo', 2026, NULL, 'Lajedo — PE', NULL, 'Participação', 'trofeu', 'Peça do Car Rock Festival 2026, com guitarra, carro amarelo e motocicleta.', 'A peça identifica o Car Rock Festival de Lajedo como encontro de carros antigos e motocicletas. O ano 2026 aparece na base.', '/media/trofeus/2026-car-rock-festival-lajedo.jpg', 'Participação', 'laco', true),
  ('2026-toritama-motofest', 'Toritama MotoFest 2026', 2026, '2026-09-25', 'Toritama — PE', NULL, 'Participação', 'trofeu', 'Troféu Toritama MotoFest 2026 com chamas e mãos fazendo o sinal do rock.', 'A peça traz o nome Toritama MotoFest, o ano 2026 e as datas 25, 26 e 27 de setembro. Esta edição é diferente da peça de 2025, também preservada na sala.', '/media/trofeus/2026-toritama-motofest.jpg', 'Participação', 'laco', true),
  ('sem-ano-primeiro-encontro-estradeiros-da-paixao', 'Primeiro Encontro de Motociclistas de Fazenda Nova — Estradeiros da Paixão', NULL, NULL, 'Fazenda Nova — PE', '1ª edição', 'Participação', 'trofeu', 'Placa amarela dos Estradeiros da Paixão com a inscrição Primeiro Encontro de Motociclistas de Fazenda Nova.', 'A peça amarela traz o emblema dos Estradeiros da Paixão e identifica o Primeiro Encontro de Motociclistas de Fazenda Nova. O ano do encontro não foi confirmado: “desde 2023” no emblema não é a data da edição.', '/media/trofeus/sem-ano-primeiro-encontro-estradeiros-da-paixao.jpg', 'Participação', 'laco', true),
  ('2026-capibaribe-motofest-9', 'IX Capibaribe Motofest', 2026, '2026-10-30', 'Santa Cruz do Capibaribe — PE', '9ª edição', 'Participação', 'placa', 'Placa IX Capibaribe Motofest com motociclista, cruz e brasão de Santa Cruz do Capibaribe.', 'A placa identifica o IX Capibaribe Motofest, em Santa Cruz do Capibaribe, e traz as datas 30 e 31 de outubro de 2026.', '/media/trofeus/2026-capibaribe-motofest-9.jpg', 'Participação', 'laco', true),
  ('2026-estradeiras-arretadas-5', '5º aniversário do Estradeiras Arretadas MC', 2026, '2026-08-23', 'Pernambuco', '5º aniversário', 'Presença no aniversário do clube', 'trofeu', 'Placa de madeira do 5º aniversário das Estradeiras Arretadas, com motoqueira, emblema e data 23/08/2026.', 'A peça celebra o 5º aniversário das Estradeiras Arretadas MC, em Pernambuco. A data gravada é 23 de agosto de 2026. As peças do 2º e do 4º aniversário continuam na coleção.', '/media/trofeus/2026-estradeiras-arretadas-5.jpg', 'Participação', 'laco', true),
  ('sem-ano-mulheres-no-asfalto-15', 'Mulheres no Asfalto — 15 anos', NULL, NULL, 'Olinda — PE', '15 anos', 'Comemoração', 'placa', 'Peça circular clara com corda e emblema Mulheres no Asfalto, Olinda, edição comemorativa de 15 anos.', 'Peça circular com borda de corda, emblema Mulheres no Asfalto e identificação de Olinda. A inscrição indica uma edição comemorativa de 15 anos, sem ano confirmado.', '/media/trofeus/sem-ano-mulheres-no-asfalto-15.jpg', 'Participação', 'laco', true),
  ('sem-ano-anjos-do-asfalto-2', '2º aniversário do Anjos do Asfalto Moto Clube', NULL, NULL, 'Pernambuco', '2º aniversário', 'Presença no aniversário do clube', 'trofeu', 'Troféu Anjos do Asfalto Moto Clube PE, 2º aniversário, com caveira de cartola e base roxa.', 'A peça traz o nome Anjos do Asfalto Moto Clube — PE, a inscrição “2º aniversário” e “#eufui”. O ano do encontro não foi confirmado.', '/media/trofeus/sem-ano-anjos-do-asfalto-2.jpg', 'Participação', 'laco', true),
  ('2025-bate-e-volta-joao-alfredo-12', '12º Bate e Volta de João Alfredo', 2025, NULL, 'João Alfredo — PE', '12ª edição', 'Participação', 'trofeu', 'Placa do 12º Bate e Volta de João Alfredo, 2025, com motocicleta e brasão municipal na base.', 'A peça identifica o 12º Bate e Volta de João Alfredo, em Pernambuco, e o ano 2025. É um encontro diferente do Camping Moto Casais, cuja peça permanece na sala.', '/media/trofeus/2025-bate-e-volta-joao-alfredo-12.jpg', 'Participação', 'laco', true)
